#include <memory>
#include <string>
#include <vector>

struct Widget { std::string name; };

std::unique_ptr<Widget> make_widget(std::string name) {   // factory: caller owns.
    return std::make_unique<Widget>(Widget{std::move(name)});
}

void show(const Widget& w);           // just uses it: plain reference, no ownership.

int main() {
    std::unique_ptr<Widget> w = make_widget("button");     // exclusive owner.
    show(*w);                                              // borrow.
    std::vector<std::unique_ptr<Widget>> panel;
    panel.push_back(std::move(w));                         // transfer; w is now null.

    auto cfg = std::make_shared<std::string>("dark");      // genuinely shared config.
    std::weak_ptr<std::string> observer = cfg;             // watches, doesn't own.
    if (auto p = observer.lock()) { /* use *p while it exists. */ }
}                                                          // everything freed automatically.
```

| Situation | Use |
|---|---|
| one clear owner. | `std::unique_ptr<T>`. |
| truly shared lifetime. | `std::shared_ptr<T>`. |
| observe without owning a shared object. | `std::weak_ptr<T>`. |
| function only uses the object. | `T&`, `const T&` or `T*`. |

